function setProgress(n,text){const v=Math.max(0,Math.min(100,Math.round(n)));els.progress.value=v;els.percentText.textContent=`${v}%`;if(text)els.statusText.textContent=text;}
function sleep(ms=0){return new Promise(r=>setTimeout(r,ms));}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function cap(s){return s?s[0].toUpperCase()+s.slice(1).toLowerCase():'';}
function unique(a){return[...new Set(a)];}
function normalizeText(s){return String(s||'').trim().replace(/\s+/g,' ');}
function safeFilename(s){return (String(s||'release').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,72)||'release');}
function pick(arr,rng){return arr[Math.floor(rng()*arr.length)];}
function xmur3(str){let h=1779033703^str.length;for(let i=0;i<str.length;i++){h=Math.imul(h^str.charCodeAt(i),3432918353);h=h<<13|h>>>19;}return function(){h=Math.imul(h^(h>>>16),2246822507);h=Math.imul(h^(h>>>13),3266489909);return(h^=h>>>16)>>>0;};}
