function numInput(el){const n=Number(el?.value);return Number.isFinite(n)&&n>=0?n:0;}
function money(n){return`NZ$${Number(n||0).toFixed(2)}`;}
function pct(n){return`${(Number(n||0)*100).toFixed(1)}%`;}
function escapeHtml(s){return String(s).replace(/[&<>\"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[ch]||ch));}
function textBlob(s,type='text/plain;charset=utf-8'){return new Blob([s],{type});}
function downloadBlob(blob,name){if(!blob)return;const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);}

function getEarningsStrategy(){
  const commercial=numInput(els.commercialEarnings),tiktok=numInput(els.tiktokEarnings),other=numInput(els.otherEarnings),total=commercial+tiktok+other;
  const cs=total?commercial/total:0,ts=total?tiktok/total:0,os=total?other/total:0;let focus='Balanced growth',code='balanced';
  if(cs>=.55){focus='Commercial licensing first';code='commercial';}
  else if(ts>=.45){focus='TikTok first';code='tiktok';}
  else if(cs+ts>=.65){focus='Commercial + TikTok';code='commercial_tiktok';}
  return{commercial,tiktok,other,total,commercialShare:cs,tiktokShare:ts,otherShare:os,focus,code};
}
function renderEarnings(){
  const s=getEarningsStrategy();els.earningsTotal.textContent=money(s.total);els.commercialShare.textContent=pct(s.commercialShare);els.tiktokShare.textContent=pct(s.tiktokShare);els.commercialBar.style.width=`${s.commercialShare*100}%`;els.tiktokBar.style.width=`${s.tiktokShare*100}%`;els.otherBar.style.width=`${s.otherShare*100}%`;els.strategyBadge.textContent=s.focus;
  let action='Build a balanced release pack with clean metadata, hooks and a steady release schedule.';
  if(s.code==='commercial')action='Prioritize clean full-length masters, instrumental alternates, cue-sheet metadata and licensing-ready assets, while still making TikTok hooks.';
  if(s.code==='tiktok')action='Prioritize fast hooks, vertical promo assets and short-form captions, while keeping the full licensing pack.';
  if(s.code==='commercial_tiktok')action='Prioritize both licensing-ready masters and short-form hook assets.';
  els.earningsInsight.innerHTML=`<strong>${escapeHtml(s.focus)}</strong><br>${s.total?`Current mix: ${pct(s.commercialShare)} commercial licensing, ${pct(s.tiktokShare)} TikTok.`:'Enter earnings to build a strategy.'}<br>${escapeHtml(action)}`;
}
function persistEarnings(){try{localStorage.setItem(EARNINGS_KEY,JSON.stringify({commercial:els.commercialEarnings.value,tiktok:els.tiktokEarnings.value,other:els.otherEarnings.value,autopilot:els.growthAutopilot.checked}));}catch(_){}renderEarnings();}
function loadEarnings(){try{const v=JSON.parse(localStorage.getItem(EARNINGS_KEY)||'null');if(!v)return;if(v.commercial!=null)els.commercialEarnings.value=v.commercial;if(v.tiktok!=null)els.tiktokEarnings.value=v.tiktok;if(v.other!=null)els.otherEarnings.value=v.other;if(typeof v.autopilot==='boolean')els.growthAutopilot.checked=v.autopilot;}catch(_){}}
async function importEarningsFile(){const f=els.earningsFile.files?.[0];if(!f)return;const t=await f.text();let c=0,k=0,o=0;for(const line of t.split(/\r?\n/)){const nums=(line.match(/-?\d+(?:\.\d+)?/g)||[]).map(Number).filter(Number.isFinite);if(!nums.length)continue;const v=nums[nums.length-1];if(/commercial\s+music\s+licens/i.test(line))c+=Math.max(0,v);else if(/tiktok/i.test(line))k+=Math.max(0,v);else if(/spotify|apple|youtube|amazon|other|stream/i.test(line))o+=Math.max(0,v);}if(c||k||o){els.commercialEarnings.value=c.toFixed(3);els.tiktokEarnings.value=k.toFixed(3);els.otherEarnings.value=o.toFixed(3);els.earningsImportStatus.textContent='Imported earnings totals from the selected file.';persistEarnings();}else els.earningsImportStatus.textContent='I could not find recognizable Commercial Music Licensing or TikTok rows in that file.';}

function persistProfile(){try{const remember=!!els.rememberStudioToken.checked;const obj={artist:els.artistName.value,songwriter:els.songwriter.value,producer:els.producer.value,label:els.labelName.value,vocalMode:els.vocalMode.value,arrangement:els.singerArrangement.value,maleVoice:els.maleVoice.value,femaleVoice:els.femaleVoice.value,vocalLevel:els.vocalLevel.value,localPerformance:els.localPerformance.value,studioModel:els.studioModel.value,studioApiUrl:els.studioApiUrl.value.trim(),rememberStudioToken:remember,studioToken:remember?els.studioApiToken.value:'',chorusTogether:els.chorusTogether.checked,autoCleanLyrics:els.autoCleanLyrics.checked};localStorage.setItem(PROFILE_KEY,JSON.stringify(obj));if(!remember)sessionStorage.setItem('corey-vibe-studio-token-v6',els.studioApiToken.value||'');}catch(_){}}
