function parseMetadataText(text){const out={};for(const raw of String(text||'').split(/\r?\n/)){const m=raw.match(/^\s*([^:]+):\s*(.*?)\s*$/);if(m)out[m[1].trim().toLowerCase()]=m[2].trim();}const pm=String(text||'').match(/\nPROMPT\s*\n([\s\S]*?)(?:\n\s*NOTES|$)/i);if(pm)out.prompt=normalizeText(pm[1]);return out;}
function renderImportStatus(){if(!state.importedLyrics&&!state.importedMetadata){els.importBadge.textContent='optional';els.importStatus.textContent='No imported song loaded. A prompt will create a new release from scratch.';return;}const title=state.importedMetadata?.['track title']||'Imported song';els.importBadge.textContent='loaded';els.importStatus.innerHTML=`<strong>${escapeHtml(title)}</strong> is loaded.${state.importChanges.length?` Lyric quality check changed ${state.importChanges.length} line(s).`:''}`;}
async function loadSelectedImports(){try{const lf=els.lyricsImportFile.files?.[0],mf=els.metadataImportFile.files?.[0];if(!lf&&!mf)throw new Error('Choose a lyrics or metadata TXT file first.');if(lf)state.importedLyrics=await lf.text();if(mf){const t=await mf.text();state.importedMetadata=parseMetadataText(t);if(!els.prompt.value&&state.importedMetadata.prompt)els.prompt.value=state.importedMetadata.prompt;}renderImportStatus();}catch(e){els.importStatus.textContent=e.message||String(e);}}
async function loadUpliftingExample(){try{const [lr,mr]=await Promise.all([fetch('./into_the_uplifting_lyrics.txt'),fetch('./into_the_uplifting_metadata.txt')]);if(!lr.ok||!mr.ok)throw new Error('Example files were not found.');state.importedLyrics=await lr.text();state.importedMetadata=parseMetadataText(await mr.text());els.prompt.value=state.importedMetadata.prompt||'emotional uplifting pop song about rebuilding your life and refusing to give up';els.style.value='pop';if(state.importedMetadata.bpm){}renderImportStatus();}catch(e){els.importStatus.textContent='Could not load example: '+(e.message||e);}}
function clearImported(){state.importedLyrics='';state.importedMetadata=null;state.importChanges=[];if(els.lyricsImportFile)els.lyricsImportFile.value='';if(els.metadataImportFile)els.metadataImportFile.value='';renderImportStatus();}

function inferStyle(prompt){const p=prompt.toLowerCase();if(/rap|hip.?hop|trap|bars|808/.test(p))return'hiphop';if(/dance|club|edm|party|festival|house/.test(p))return'dance';if(/cinematic|movie|epic|trailer|orchestra|dramatic/.test(p))return'cinematic';if(/ambient|sleep|calm|relax|meditat|dreamy/.test(p))return'ambient';return'pop';}
function inferEnergy(prompt,style){const p=prompt.toLowerCase();if(/high energy|powerful|hype|big|wild|party|fast|explosive/.test(p))return'high';if(/soft|slow|calm|gentle|sad|quiet|peaceful/.test(p))return'low';if(style==='dance')return'high';return'medium';}
function inferArrangement(prompt){const chosen=els.singerArrangement.value;if(chosen!=='auto')return chosen;const p=prompt.toLowerCase();if(/duet|male and female|man and woman|two singers|both voices/.test(p))return'duet';if(/female singer|woman singing|female vocal|girl voice/.test(p))return'female';return'male';}
function themeWords(prompt){const stop=new Set('about with from into that this then when where your you and the for but not are was were have has had one two song music make create feel like just very really more less some over under through around without after before'.split(' '));return unique(prompt.toLowerCase().replace(/[^a-z0-9' -]/g,' ').split(/\s+/).filter(w=>w.length>3&&!stop.has(w))).slice(0,16);}
function makeTitle(prompt,rng){const words=themeWords(prompt),fallbacks=['One More Light','Open Road','Still Moving','After Midnight','Make It Mine','Second Sunrise','Hold The Line'];if(words.length<2)return pick(fallbacks,rng);const forms=[()=>{const a=pick(words,rng),rest=words.filter(w=>w!==a);return`${cap(a)} ${cap(pick(rest.length?rest:words,rng))}`;},()=>`${cap(pick(words,rng))} Again`,()=>`One More ${cap(pick(words,rng))}`,()=>`${cap(pick(words,rng))} Tonight`,()=>`Into The ${cap(pick(words,rng))}`];let title=pick(forms,rng)();if(title.split(' ').filter(Boolean).length<2)title=pick(fallbacks,rng);return title.replace(/\b(And|The|For|With)\b$/,'').trim();}
function lyricThemeLine(prompt,rng){const words=themeWords(prompt);const a=words[0]||'future',b=words[1]||'dream';const options=[`I turn the weight of ${a} into a reason to rise`,`I keep a little ${b} alive when the lights get low`,`Every hard day taught me what I need to know`,`I found another road when the old one disappeared`];return pick(options,rng);}
function makeLyrics(prompt,title,rng){
  const v1=['I kept a little spark when the room went dark','Another long night and I still chose the road','I watched the small signs turn into a start','I had a quiet dream I was not ready to fold'];
  const v2=['Every small step leaves a mark on the way','I turn the hard days into something I can use','The numbers move slowly but I still make a play','I found another reason every time I had to choose'];
  const pre=['No perfect map, no promise in the sky','I only need a heartbeat and a reason to try','I can hear tomorrow getting closer tonight','I keep turning pressure into fuel for the climb'];
  const p1=pick(pre,rng),p2=pick(pre.filter(x=>x!==p1),rng);const hook=[`This is ${title}, I am making it mine`,'One more chance, one more beat, one more light','I am still moving when the road gets tight','I came this far, I am not leaving tonight'];const h1=pick(hook.slice(1),rng),h2=pick(hook.slice(1).filter(x=>x!==h1),rng);
  return `[Title: ${title}]\n\n[Verse 1]\n${pick(v1,rng)}\n${lyricThemeLine(prompt,rng)}\n${pick(v2,rng)}\nI take what I have and I give it some time\n\n[Pre-Chorus]\n${p1}\n${p2}\n\n[Chorus]\n${hook[0]}\n${h1}\n${h2}\nOne more heartbeat, one more reason to rise\n\n[Verse 2]\n${pick(v1,rng)}\n${pick(v2,rng)}\nI keep the little wins and I learn from the pain\nIf I get one more shot I will do it again\n\n[Bridge]\nNo shortcut, no borrowed name\nJust another page and a brand new frame\nI keep moving forward, I keep choosing the climb\nBuilding this life one beat at a time\n\n[Final Chorus]\n${hook[0]}\nOne more chance, one more beat, one more light\nI am still moving when the road gets tight\nOne beat at a time, one more try.`;
}
function cleanLyrics(text,prompt,seed){const rng=mulberry32(seed),changes=[];const bad=/^(the story is|keywords?:|prompt:|genre:|mood:|emotional,|uplifting,|rebuilding,)/i;const lines=String(text||'').split(/\r?\n/).map(line=>{const t=line.trim();if(t&&!/^\[.*\]$/.test(t)&&bad.test(t)){const replacement=lyricThemeLine(prompt,rng);changes.push({from:t,to:replacement});return replacement;}return line;});return{text:lines.join('\n'),changes};}
function replaceTitleInLyrics(text,oldTitle,newTitle){const esc=String(oldTitle||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');let out=String(text||'');if(esc)out=out.replace(new RegExp(esc,'g'),newTitle);return out.replace(/^\[Title: .*?\]/m,`[Title: ${newTitle}]`);}

function addOsc(ctx,dest,start,dur,freq,type,gain,attack=.008,release=.07,detune=0){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);o.detune.value=detune;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),start+attack);const hold=Math.max(start+attack+.005,start+dur-release);g.gain.setValueAtTime(Math.max(.0002,gain),hold);g.gain.exponentialRampToValueAtTime(.0001,start+dur);o.connect(g).connect(dest);o.start(start);o.stop(start+dur+.03);}
