async function getStudioModule(){if(!studioModulePromise)studioModulePromise=import('./studio-engine.mjs');return await studioModulePromise;}
function studioConfig(){return{baseUrl:els.studioApiUrl.value.trim(),token:els.studioApiToken.value.trim(),model:els.studioModel.value||'acestep-v15-sft'};}
async function testStudioConnection(){const cfg=studioConfig();if(!cfg.baseUrl){els.studioBadge.textContent='not configured';els.studioStatus.textContent='Enter an HTTPS Studio API URL first.';return false;}els.testStudioBtn.disabled=true;els.studioStatus.textContent='Testing Studio server…';try{const mod=await getStudioModule(),info=await mod.testStudioConnection(cfg);els.studioBadge.textContent='connected';els.studioBadge.classList.add('success');els.studioStatus.textContent=`Connected to ${info.service||'ACE-Step'}${info.version?` ${info.version}`:''}. Auto mode will use Studio Singer.`;persistProfile();return true;}catch(err){els.studioBadge.textContent='offline';els.studioBadge.classList.remove('success');els.studioStatus.textContent='Studio connection failed: '+(err?.message||String(err));return false;}finally{els.testStudioBtn.disabled=false;}}
async function addVocals(audio,lyrics,prompt){const chosen=els.vocalMode.value,arrangement=inferArrangement(prompt);if(chosen==='instrumental')return{masterBlob:audio.blob,masterBuffer:audio.buffer,vocalStemBlob:null,maleStemBlob:null,femaleStemBlob:null,engine:'instrumental',arrangementResolved:'instrumental',warning:null};const cfg=studioConfig(),shouldTryStudio=chosen==='studio'||(chosen==='auto'&&!!cfg.baseUrl);if(shouldTryStudio){try{els.statusText.textContent='Sending lyrics to Studio Singer…';const mod=await getStudioModule();const studio=await mod.generateStudioSong({...cfg,prompt,lyrics,duration:Number(els.length.value),bpm:audio.bpm,arrangement,onStatus:t=>{els.statusText.textContent=t;}});return{masterBlob:studio.masterBlob,masterBuffer:studio.masterBuffer,vocalStemBlob:null,maleStemBlob:null,femaleStemBlob:null,engine:'ace-step-studio',arrangementResolved:arrangement,warning:null,studioMeta:studio.meta||null};}catch(err){const msg=`Studio Singer could not finish (${err?.message||err}). Fast Local neural vocals were used instead.`;els.statusText.textContent=msg;const engine=await waitForVocalEngine();const local=await engine.renderVocalMix({instrumentalBuffer:audio.buffer,lyrics,arrangement,maleVoice:els.maleVoice.value,femaleVoice:els.femaleVoice.value,level:Number(els.vocalLevel.value||.9),mode:'neural',performanceMode:els.localPerformance.value,chorusTogether:els.chorusTogether.checked,onStatus:t=>{els.statusText.textContent=t;}});local.warning=msg+(local.warning?` ${local.warning}`:'');return local;}}const engine=await waitForVocalEngine(),mode=chosen==='auto'?'neural':chosen;return await engine.renderVocalMix({instrumentalBuffer:audio.buffer,lyrics,arrangement,maleVoice:els.maleVoice.value,femaleVoice:els.femaleVoice.value,level:Number(els.vocalLevel.value||.9),mode,performanceMode:els.localPerformance.value,chorusTogether:els.chorusTogether.checked,onStatus:t=>{els.statusText.textContent=t;}});}

function canvasBlob(canvas,type='image/png',quality=.95){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Could not create image.')),type,quality));}
function seededGradient(ctx,w,h,seed){const rng=mulberry32(seed),h1=Math.floor(rng()*360),h2=(h1+70+Math.floor(rng()*120))%360,g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,`hsl(${h1} 70% 34%)`);g.addColorStop(.55,`hsl(${(h1+h2)/2} 68% 20%)`);g.addColorStop(1,`hsl(${h2} 72% 29%)`);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);for(let i=0;i<32;i++){ctx.fillStyle=`hsla(${(h1+i*9)%360} 90% 70% / ${.02+rng()*.06})`;ctx.beginPath();ctx.arc(rng()*w,rng()*h,80+rng()*380,0,Math.PI*2);ctx.fill();}}
function fitText(ctx,text,maxWidth,start){let size=start;while(size>70){ctx.font=`900 ${size}px system-ui,sans-serif`;if(ctx.measureText(text).width<=maxWidth)break;size-=8;}return size;}
async function makeCover(title,artist,seed){const c=els.coverCanvas,ctx=c.getContext('2d');seededGradient(ctx,c.width,c.height,seed);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.shadowColor='rgba(0,0,0,.55)';ctx.shadowBlur=26;const size=fitText(ctx,title,2500,270);ctx.font=`900 ${size}px system-ui,sans-serif`;const words=title.split(' '),lines=[];let line='';for(const word of words){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>2400&&line){lines.push(line);line=word;}else line=test;}if(line)lines.push(line);const lh=size*1.08,startY=1500-(lines.length-1)*lh/2;lines.forEach((x,i)=>ctx.fillText(x,1500,startY+i*lh));ctx.font='800 95px system-ui,sans-serif';ctx.fillStyle='rgba(255,255,255,.92)';ctx.fillText(artist.toUpperCase(),1500,2600);return await canvasBlob(c);}
async function makeVerticalPromo(title,artist,seed){const c=els.promoCanvas,ctx=c.getContext('2d');seededGradient(ctx,c.width,c.height,seed^0x9E3779B9);ctx.textAlign='center';ctx.fillStyle='#fff';ctx.shadowColor='rgba(0,0,0,.55)';ctx.shadowBlur=18;const size=fitText(ctx,title,900,115);ctx.font=`900 ${size}px system-ui,sans-serif`;const words=title.split(' '),lines=[];let line='';for(const word of words){const t=line?`${line} ${word}`:word;if(ctx.measureText(t).width>900&&line){lines.push(line);line=word;}else line=t;}if(line)lines.push(line);let y=850-lines.length*size*.45;for(const x of lines){ctx.fillText(x,540,y);y+=size*1.08;}ctx.font='800 46px system-ui,sans-serif';ctx.fillStyle='rgba(255,255,255,.92)';ctx.fillText(artist.toUpperCase(),540,1550);ctx.font='700 34px system-ui,sans-serif';ctx.fillText('NEW MUSIC',540,1640);return await canvasBlob(c);}

function sliceBufferToWav(buffer,startSec,durationSec){const sr=buffer.sampleRate,start=Math.floor(startSec*sr),len=Math.min(Math.floor(durationSec*sr),Math.max(0,buffer.length-start)),ctx=new OfflineAudioContext(buffer.numberOfChannels,Math.max(1,len),sr),src=ctx.createBufferSource();src.buffer=buffer;src.connect(ctx.destination);src.start(0,startSec,durationSec);return ctx.startRendering().then(audioBufferToWav);}
async function buildPromoClips(audio){const start=Math.max(0,Math.min(audio.duration*.28,audio.duration-30));return{hook15:await sliceBufferToWav(audio.buffer,start,Math.min(15,audio.duration-start)),hook30:await sliceBufferToWav(audio.buffer,start,Math.min(30,audio.duration-start))};}

function suggestedDate(){const d=new Date();d.setDate(d.getDate()+21);return d.toISOString().slice(0,10);}
function genreName(style){return({pop:'Pop',hiphop:'Hip-Hop/Rap',dance:'Dance',ambient:'Electronic',cinematic:'Pop'})[style]||'Pop';}
function buildRelease({prompt,title,style,energy,audio,seed,lyrics,vocal}){const strategy=getEarningsStrategy();return{version:'v6',title,artist:normalizeText(els.artistName.value)||'Corey Vibe',songwriter:normalizeText(els.songwriter.value)||'Corey Vibe',producer:normalizeText(els.producer.value)||'Corey Vibe',label:normalizeText(els.labelName.value)||'Independent',genre:genreName(style),language:'English',explicit:'No — review lyrics before submission',release_date_suggestion:state.importedMetadata?.['suggested release date']||suggestedDate(),bpm:audio.bpm,duration_seconds:Math.round(audio.duration),sample_rate_hz:44100,bit_depth:16,channels:2,cover_pixels:'3000×3000 PNG',prompt,style,energy,lyrics,seed,vocal_engine:vocal.engine,vocal_arrangement:vocal.arrangementResolved,vocal_male_voice:vocal.engine==='ace-step-studio'?'Studio model-controlled':(vocal.arrangementResolved==='female'||vocal.arrangementResolved==='instrumental'?'Not used':els.maleVoice.value),vocal_female_voice:vocal.engine==='ace-step-studio'?'Studio model-controlled':(vocal.arrangementResolved==='male'||vocal.arrangementResolved==='instrumental'?'Not used':els.femaleVoice.value),instrumental_alternate_note:vocal.engine==='ace-step-studio'?'Procedural alternate generated locally; it is not an extracted stem of the Studio full mix.':'Matched local backing track',vocal_warning:vocal.warning||'',growth_strategy:strategy,project_royalty_share:'0%',created_at:new Date().toISOString()};}
function metadataText(r){return`SOUNDON RELEASE METADATA\n\nTrack title: ${r.title}\nPrimary artist: ${r.artist}\nSongwriter / composer: ${r.songwriter}\nProducer: ${r.producer}\nLabel / imprint: ${r.label}\nGenre: ${r.genre}\nLanguage: ${r.language}\nExplicit: ${r.explicit}\nSuggested release date: ${r.release_date_suggestion}\nBPM: ${r.bpm}\nDuration: ${r.duration_seconds} seconds\nAudio: ${r.sample_rate_hz} Hz / ${r.bit_depth}-bit / ${r.channels} channels / WAV PCM\nCover: ${r.cover_pixels}\nVocal engine: ${r.vocal_engine}\nVocal arrangement: ${r.vocal_arrangement}\nMale voice preset: ${r.vocal_male_voice}\nFemale voice preset: ${r.vocal_female_voice}\nInstrumental alternate note: ${r.instrumental_alternate_note||'Matched local backing track'}\n\nPROMPT\n${r.prompt}\n\nNOTES\nReview contributor names, explicit-content selection, genre, release date and any distributor-required automated-content disclosures before final submission.`;}
function checklistText(r){return`RELEASE CHECKLIST\n\n✓ WAV master: 44.1 kHz / 16-bit / stereo\n✓ 3000×3000 cover PNG\n✓ Lyrics included\n✓ Metadata included\n✓ Instrumental alternate included when vocals are enabled\n✓ Vocal stem(s) included when generated\n✓ Commercial licensing cue sheet included\n✓ 15s + 30s promotional hooks included when Growth Autopilot is on\n\nBefore submission:\n- Listen to the full master from start to finish.\n- Verify title, artist, songwriter and producer.\n- Review lyrics for explicit content.\n- Confirm release date and genre.\n- Follow any disclosure requirements imposed by the distributor or streaming platform.\n`;} 
function rightsText(r){return`COREY VIBE AUTO RELEASE STUDIO — OUTPUT RIGHTS RECORD\n\nTrack: ${r.title}\nArtist: ${r.artist}\nCreated: ${r.created_at}\n\nThe Corey Vibe Auto Release Studio project claims no ownership share in this output and takes 0% of royalties or revenue. The user may use, edit, distribute, monetize and commercially release the project-generated files to the extent the project itself has rights to grant.\n\nFast Local backing tracks are procedurally synthesized by the website. Fast Local neural vocals use third-party open-source software/model components. Studio Singer outputs are generated by the separately configured ACE-Step server/model. Third-party components remain under their own licenses. This document is not a guarantee that an output is copyrightable in every jurisdiction, that it never resembles existing material, or that a distributor will accept it. The user remains responsible for final review, contributor credits, platform rules and any required disclosures.\n`;}
function commercialLicensingText(r){return`COMMERCIAL LICENSING CUE SHEET\n\nTitle: ${r.title}\nArtist: ${r.artist}\nWriter/Composer: ${r.songwriter}\nProducer: ${r.producer}\nLabel: ${r.label}\nGenre: ${r.genre}\nBPM: ${r.bpm}\nDuration: ${r.duration_seconds}s\nVocal arrangement: ${r.vocal_arrangement}\nInstrumental alternate: Yes when vocals are enabled\nClean/Explicit: ${r.explicit}\nMood keywords: ${themeWords(r.prompt).join(', ')}\n\nSuggested uses: social video, creator content, lifestyle montage, motivational content, general sync pitching where the licensee and distributor terms permit.\n`;}
function tiktokCaptionsText(r){return[`New music from ${r.artist} 🎵 ${r.title}`,`That moment you refuse to give up. ${r.title} — ${r.artist}`,`Which part hits hardest? 🎧 ${r.title}`,`Turn it up 🔊 ${r.title} by ${r.artist}`,`A new Corey Vibe release is on the way ✨`].join('\n');}
function shortVideoIdeasText(r){return`SHORT VIDEO IDEAS\n\n1. Put the strongest chorus line on screen over the 15s hook.\n2. Show a simple before/after story matching the song theme.\n3. Film a face-to-camera introduction, then cut into the hook.\n4. Use the 30s hook with lyric captions and changing background shots.\n5. Make a second clip explaining what inspired “${r.title}”.\n`;} 
function spotifyPitchText(r){return`${r.title} is a ${r.genre.toLowerCase()} track by ${r.artist} at ${r.bpm} BPM. The song centers on ${themeWords(r.prompt).slice(0,6).join(', ')} and uses a ${r.vocal_arrangement} vocal arrangement. The release is supported with short-form hook edits and vertical promotional assets.`;}
function releaseScheduleText(r){const d=new Date(r.release_date_suggestion+'T12:00:00');const day=n=>{const x=new Date(d);x.setDate(x.getDate()+n);return x.toISOString().slice(0,10);};return`AUTOMATIC RELEASE SCHEDULE\n\n${day(-14)} — Final listen, metadata and cover review\n${day(-10)} — Upload to distributor if possible\n${day(-7)} — Teaser using 15s hook\n${day(-3)} — Second teaser / lyric clip\n${day(0)} — Release day post + 30s hook\n${day(2)} — Behind-the-song short\n${day(5)} — Alternate clip with a different chorus line\n${day(10)} — Review earnings/analytics and update the next release plan\n`;}
function growthPlanText(r){return`AUTOMATIC GROWTH PLAN\n\nRevenue focus: ${r.growth_strategy.focus}\nCommercial licensing share: ${pct(r.growth_strategy.commercialShare)}\nTikTok share: ${pct(r.growth_strategy.tiktokShare)}\n\n${commercialLicensingText(r)}\n${tiktokCaptionsText(r)}\n\n${shortVideoIdeasText(r)}\n\nSPOTIFY PITCH STARTER\n${spotifyPitchText(r)}\n\n${releaseScheduleText(r)}`;}

function validateRelease(r){const checks=[{ok:SELFTEST||r.duration_seconds>=60,name:'Track length',detail:`${r.duration_seconds}s`},{ok:r.sample_rate_hz>=44100,name:'Sample rate',detail:`${r.sample_rate_hz} Hz`},{ok:r.bit_depth>=16,name:'Bit depth',detail:`${r.bit_depth}-bit`},{ok:!!state.coverBlob,name:'Cover artwork',detail:r.cover_pixels},{ok:!!r.title&&!!r.artist,name:'Metadata',detail:'Title + artist ready'},{ok:r.vocal_arrangement==='instrumental'||r.vocal_engine==='ace-step-studio'||!!state.vocalStemBlob,name:'Vocal render',detail:r.vocal_arrangement==='instrumental'?'Instrumental selected':(r.vocal_engine==='ace-step-studio'?'Studio full-song mix ready':`${r.vocal_arrangement} vocal stem ready`)}];return checks;}
function renderChecks(){const checks=validateRelease(state.release);els.checks.innerHTML=checks.map(c=>`<div class="check"><span class="icon">${c.ok?'✅':'⚠️'}</span><div><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.detail)}</small></div></div>`).join('');const all=checks.every(c=>c.ok);els.readyBadge.textContent=all?'Release specs passed':'Review checks';els.readyBadge.classList.toggle('success',all);return all;}
function renderDetails(r){const pairs=[['Title',r.title],['Artist',r.artist],['Songwriter',r.songwriter],['Producer',r.producer],['Genre',r.genre],['Vocal engine',r.vocal_engine],['Arrangement',r.vocal_arrangement],['Male voice',r.vocal_male_voice],['Female voice',r.vocal_female_voice],['Suggested release',r.release_date_suggestion],['Audio',`${r.sample_rate_hz} Hz • ${r.bit_depth}-bit WAV • ${r.duration_seconds}s`],['Cover',r.cover_pixels],['Website royalty share',r.project_royalty_share]];els.releaseDetails.innerHTML=pairs.map(([k,v])=>`<dt>${escapeHtml(k)}</dt><dd>${escapeHtml(String(v))}</dd>`).join('');}
function refreshReleaseUI(){const r=state.release;if(!r)return;els.trackTitle.textContent=r.title;els.titleInput.value=r.title;els.trackSummary.textContent=`${r.genre} • ${r.bpm} BPM • ${r.duration_seconds}s • ${r.vocal_arrangement}`+(r.vocal_warning?' • fallback used':'');els.lyricsText.textContent=r.lyrics;renderDetails(r);renderChecks();els.growthStrategySummary.textContent=`${r.growth_strategy.focus}. Hooks, licensing metadata and vertical promo assets are ready.`;els.growthPreview.textContent=growthPlanText(r);els.maleStemBtn.disabled=!state.maleStemBlob;els.femaleStemBtn.disabled=!state.femaleStemBlob;els.vocalStemBtn.disabled=!state.vocalStemBlob;els.instrumentalBtn.disabled=!state.instrumentalBlob;}

function saveHistory(r){try{const old=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]'),next=[{title:r.title,created_at:r.created_at,prompt:r.prompt,arrangement:r.vocal_arrangement},...old].slice(0,12);localStorage.setItem(HISTORY_KEY,JSON.stringify(next));renderHistory();}catch(_){}}
function renderHistory(){let arr=[];try{arr=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');}catch(_){}if(!arr.length){els.historyList.innerHTML='<p class="hint">No projects yet.</p>';return;}els.historyList.innerHTML=arr.map(x=>`<div class="history-item"><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.arrangement||'')} • ${escapeHtml(new Date(x.created_at).toLocaleString())}<br>${escapeHtml(x.prompt||'')}</small></div><div class="history-actions"><button class="secondary small history-use" data-prompt="${escapeHtml(x.prompt||'')}">Reuse prompt</button></div></div>`).join('');els.historyList.querySelectorAll('.history-use').forEach(b=>b.addEventListener('click',()=>{els.prompt.value=b.dataset.prompt||'';window.scrollTo({top:0,behavior:'smooth'});}));}

function runDiagnostics(){const tests=[{ok:typeof window.OfflineAudioContext==='function',name:'Audio rendering',detail:'OfflineAudioContext'},{ok:!!document.createElement('canvas').getContext,name:'Artwork generation',detail:'Canvas support'},{ok:typeof Blob==='function'&&typeof URL.createObjectURL==='function',name:'Downloads',detail:'Blob + object URL'},{ok:(()=>{try{localStorage.setItem('__cv6','1');localStorage.removeItem('__cv6');return true;}catch(_){return false;}})(),name:'Saved settings',detail:'Local storage'},{ok:'TextEncoder'in window,name:'Release ZIP',detail:'TextEncoder support'},{ok:location.protocol!=='file:',name:'Neural singer hosting',detail:location.protocol!=='file:'?'Ready for lazy model loading':'Open through GitHub Pages, not file://'},{ok:!!navigator.gpu,name:'WebGPU acceleration',detail:navigator.gpu?'Available — Fast Local can try GPU acceleration':'Not available — WASM fallback will be used'}];els.diagnosticsList.innerHTML=tests.map(t=>`<div class="check"><span class="icon">${t.ok?'✅':'⚠️'}</span><div><strong>${escapeHtml(t.name)}</strong><small>${escapeHtml(t.detail)}</small></div></div>`).join('');return tests.every(t=>t.ok);}

function cleanupUrls(){if(state.wavUrl)URL.revokeObjectURL(state.wavUrl);if(state.coverUrl)URL.revokeObjectURL(state.coverUrl);state.wavUrl=null;state.coverUrl=null;}
async function createFullRelease(){const importedPrompt=state.importedMetadata?.prompt||'',prompt=normalizeText(els.prompt.value||importedPrompt);if(!prompt&&!state.importedLyrics){els.prompt.focus();setProgress(0,'Type a song prompt or import lyrics first.');return;}persistProfile();state.cancelled=false;els.createBtn.disabled=true;els.cancelBtn.disabled=false;els.resultCard.classList.add('hidden');try{setProgress(3,'Reading your prompt and imported files…');await sleep(40);const seed=xmur3(`${prompt}|${els.artistName.value}|${Date.now()}`)(),rng=mulberry32(seed),style=els.style.value==='auto'?inferStyle(prompt):els.style.value;let energy=els.energy.value==='auto'?inferEnergy(prompt,style):els.energy.value;const strategy=getEarningsStrategy();if(els.growthAutopilot.checked&&els.energy.value==='auto'&&style!=='ambient'&&(strategy.code==='commercial'||strategy.code==='tiktok'||strategy.code==='commercial_tiktok'))energy='high';const seconds=SELFTEST?4:Number(els.length.value),importedTitle=state.importedMetadata?.['track title'],title=normalizeText(importedTitle)||makeTitle(prompt,rng);let lyrics=SELFTEST?'[Verse 1]\nTest vocal line':(state.importedLyrics||makeLyrics(prompt,title,rng));if(els.autoCleanLyrics.checked){const clean=cleanLyrics(lyrics,prompt,seed^0xBEEF);lyrics=clean.text;state.importChanges=clean.changes;renderImportStatus();}setProgress(8,'Planning title, lyrics and arrangement…');const instrumental=await renderSong(prompt||title,style,seconds,energy,seed);setProgress(70,els.vocalMode.value==='instrumental'?'Keeping instrumental master…':'Creating sung-style vocals…');const vocal=await addVocals(instrumental,lyrics,prompt),finalAudio={blob:vocal.masterBlob,buffer:vocal.masterBuffer,bpm:instrumental.bpm,duration:instrumental.duration,sampleRate:44100,bitDepth:16,channels:2};setProgress(84,'Building 15s and 30s hook edits…');const clips=SELFTEST?{hook15:finalAudio.blob,hook30:finalAudio.blob}:await buildPromoClips(finalAudio);setProgress(87,'Creating 3000 × 3000 cover…');const cover=await makeCover(title,normalizeText(els.artistName.value)||'Corey Vibe',seed);setProgress(90,'Creating vertical promo artwork…');const verticalPromo=await makeVerticalPromo(title,normalizeText(els.artistName.value)||'Corey Vibe',seed);if(state.cancelled)throw new Error('Generation stopped');setProgress(94,'Preparing metadata, licensing and growth files…');const release=buildRelease({prompt,title,style,energy,audio:finalAudio,seed,lyrics,vocal});cleanupUrls();state.wavBlob=finalAudio.blob;state.instrumentalBlob=vocal.engine==='instrumental'?null:instrumental.blob;state.instrumentalAudio=instrumental;state.vocalStemBlob=vocal.vocalStemBlob;state.maleStemBlob=vocal.maleStemBlob;state.femaleStemBlob=vocal.femaleStemBlob;state.coverBlob=cover;state.release=release;state.hook15Blob=clips.hook15;state.hook30Blob=clips.hook30;state.verticalPromoBlob=verticalPromo;state.wavUrl=URL.createObjectURL(finalAudio.blob);state.coverUrl=URL.createObjectURL(cover);els.player.src=state.wavUrl;els.coverPreview.src=state.coverUrl;refreshReleaseUI();els.resultCard.classList.remove('hidden');saveHistory(release);setProgress(100,vocal.warning?'Complete — fallback vocals + release pack ready.':'Complete — vocal release pack ready.');if(vocal.warning)els.statusText.textContent+=` ${vocal.warning}`;if(!SELFTEST)els.resultCard.scrollIntoView({behavior:'smooth',block:'start'});window.__APP_TEST_RESULT__={ok:renderChecks()&&!!state.coverBlob&&!!state.wavBlob,title,arrangement:vocal.arrangementResolved,wavSize:state.wavBlob.size,coverSize:cover.size};if(SELFTEST)document.documentElement.dataset.selftest=window.__APP_TEST_RESULT__.ok?'pass':'fail';}catch(err){console.error(err);setProgress(0,err?.message==='Generation stopped'?'Stopped.':'Could not finish: '+(err?.message||String(err)));window.__APP_TEST_RESULT__={ok:false,error:err?.message||String(err)};if(SELFTEST)document.documentElement.dataset.selftest='fail';}finally{els.createBtn.disabled=false;els.cancelBtn.disabled=true;}}

async function rerenderVocalsOnly(label='Re-singing updated lyrics…'){if(!state.release||!state.instrumentalAudio)return;setProgress(70,label);const vocal=await addVocals(state.instrumentalAudio,state.release.lyrics,state.release.prompt),inst=state.instrumentalAudio,audio={blob:vocal.masterBlob,buffer:vocal.masterBuffer,bpm:inst.bpm,duration:inst.duration,sampleRate:44100,bitDepth:16,channels:2},clips=await buildPromoClips(audio);if(state.wavUrl)URL.revokeObjectURL(state.wavUrl);state.wavBlob=audio.blob;state.vocalStemBlob=vocal.vocalStemBlob;state.maleStemBlob=vocal.maleStemBlob;state.femaleStemBlob=vocal.femaleStemBlob;state.hook15Blob=clips.hook15;state.hook30Blob=clips.hook30;state.wavUrl=URL.createObjectURL(audio.blob);els.player.src=state.wavUrl;state.release.vocal_engine=vocal.engine;state.release.vocal_arrangement=vocal.arrangementResolved;state.release.vocal_warning=vocal.warning||'';refreshReleaseUI();setProgress(100,'Updated vocal master ready.');}

const CRC_TABLE=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc32(bytes){let c=0xFFFFFFFF;for(let i=0;i<bytes.length;i++)c=CRC_TABLE[(c^bytes[i])&255]^(c>>>8);return(c^0xFFFFFFFF)>>>0;}
function dosDateTime(d=new Date()){let year=Math.max(1980,d.getFullYear());return{date:((year-1980)<<9)|((d.getMonth()+1)<<5)|d.getDate(),time:(d.getHours()<<11)|(d.getMinutes()<<5)|(d.getSeconds()>>1)};}
function u16(v){const b=new Uint8Array(2);new DataView(b.buffer).setUint16(0,v,true);return b;}function u32(v){const b=new Uint8Array(4);new DataView(b.buffer).setUint32(0,v>>>0,true);return b;}function concat(parts){const len=parts.reduce((n,p)=>n+p.length,0),out=new Uint8Array(len);let o=0;for(const p of parts){out.set(p,o);o+=p.length;}return out;}
async function makeZip(files){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;const dt=dosDateTime();for(const f of files){const name=enc.encode(f.name),data=new Uint8Array(await f.blob.arrayBuffer()),crc=crc32(data),local=concat([u32(0x04034b50),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);locals.push(local);const central=concat([u32(0x02014b50),u16(20),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);centrals.push(central);offset+=local.length;}const cd=concat(centrals),ld=concat(locals),end=concat([u32(0x06054b50),u16(0),u16(0),u16(files.length),u16(files.length),u32(cd.length),u32(ld.length),u16(0)]);return new Blob([ld,cd,end],{type:'application/zip'});}
function getPackageFiles(){const r=state.release,b=safeFilename(r.title),files=[{name:'00_START_HERE.txt',blob:textBlob(growthPlanText(r))},{name:`01_${b}_vocal_master.wav`,blob:state.wavBlob}];if(state.instrumentalBlob)files.push({name:`02_${b}_instrumental.wav`,blob:state.instrumentalBlob});if(state.vocalStemBlob)files.push({name:`03_${b}_combined_vocal_stem.wav`,blob:state.vocalStemBlob});if(state.maleStemBlob)files.push({name:`04_${b}_male_vocal_stem.wav`,blob:state.maleStemBlob});if(state.femaleStemBlob)files.push({name:`05_${b}_female_vocal_stem.wav`,blob:state.femaleStemBlob});files.push({name:`06_${b}_cover.png`,blob:state.coverBlob},{name:'07_release_metadata.txt',blob:textBlob(metadataText(r))},{name:'08_lyrics.txt',blob:textBlob(r.lyrics)},{name:'09_output_rights_record.txt',blob:textBlob(rightsText(r))},{name:'10_production_proof.json',blob:textBlob(JSON.stringify(r,null,2),'application/json')},{name:'11_soundon_checklist.txt',blob:textBlob(checklistText(r))});if(els.growthAutopilot.checked){if(state.hook15Blob)files.push({name:`12_${b}_15s_hook.wav`,blob:state.hook15Blob});if(state.hook30Blob)files.push({name:`13_${b}_30s_hook.wav`,blob:state.hook30Blob});if(state.verticalPromoBlob)files.push({name:`14_${b}_vertical_1080x1920.png`,blob:state.verticalPromoBlob});files.push({name:'15_commercial_licensing_cue_sheet.txt',blob:textBlob(commercialLicensingText(r))},{name:'16_tiktok_captions.txt',blob:textBlob(tiktokCaptionsText(r))},{name:'17_short_video_ideas.txt',blob:textBlob(shortVideoIdeasText(r))},{name:'18_spotify_pitch_starter.txt',blob:textBlob(spotifyPitchText(r))},{name:'19_release_schedule.txt',blob:textBlob(releaseScheduleText(r))},{name:'20_growth_strategy.json',blob:textBlob(JSON.stringify(r.growth_strategy,null,2),'application/json')});}return files;}

for(const b of document.querySelectorAll('[data-prompt]'))b.addEventListener('click',()=>els.prompt.value=b.dataset.prompt||'');
els.createBtn.addEventListener('click',createFullRelease);els.cancelBtn.addEventListener('click',()=>{state.cancelled=true;els.statusText.textContent='Stopping after the current step…';});
els.loadImportedBtn.addEventListener('click',loadSelectedImports);els.loadUpliftingExampleBtn.addEventListener('click',loadUpliftingExample);els.clearImportedBtn.addEventListener('click',clearImported);els.earningsFile.addEventListener('change',importEarningsFile);
for(const el of [els.commercialEarnings,els.tiktokEarnings,els.otherEarnings,els.growthAutopilot])el.addEventListener('change',persistEarnings);
for(const el of [els.artistName,els.songwriter,els.producer,els.labelName,els.vocalMode,els.singerArrangement,els.maleVoice,els.femaleVoice,els.vocalLevel,els.localPerformance,els.studioModel,els.studioApiUrl,els.rememberStudioToken,els.chorusTogether,els.autoCleanLyrics])el.addEventListener('change',persistProfile);
els.studioApiToken.addEventListener('change',persistProfile);els.testStudioBtn.addEventListener('click',testStudioConnection);
els.wavBtn.addEventListener('click',()=>downloadBlob(state.wavBlob,`${safeFilename(state.release?.title)}_vocal_master.wav`));els.instrumentalBtn.addEventListener('click',()=>downloadBlob(state.instrumentalBlob,`${safeFilename(state.release?.title)}_instrumental.wav`));els.vocalStemBtn.addEventListener('click',()=>downloadBlob(state.vocalStemBlob,`${safeFilename(state.release?.title)}_combined_vocal_stem.wav`));els.maleStemBtn.addEventListener('click',()=>downloadBlob(state.maleStemBlob,`${safeFilename(state.release?.title)}_male_vocal_stem.wav`));els.femaleStemBtn.addEventListener('click',()=>downloadBlob(state.femaleStemBlob,`${safeFilename(state.release?.title)}_female_vocal_stem.wav`));els.coverBtn.addEventListener('click',()=>downloadBlob(state.coverBlob,`${safeFilename(state.release?.title)}_cover.png`));els.lyricsBtn.addEventListener('click',()=>downloadBlob(textBlob(state.release?.lyrics||''),`${safeFilename(state.release?.title)}_lyrics.txt`));els.metaBtn.addEventListener('click',()=>downloadBlob(textBlob(metadataText(state.release)),`${safeFilename(state.release?.title)}_metadata.txt`));
els.hook15Btn.addEventListener('click',()=>downloadBlob(state.hook15Blob,`${safeFilename(state.release?.title)}_15s_hook.wav`));els.hook30Btn.addEventListener('click',()=>downloadBlob(state.hook30Blob,`${safeFilename(state.release?.title)}_30s_hook.wav`));els.verticalPromoBtn.addEventListener('click',()=>downloadBlob(state.verticalPromoBlob,`${safeFilename(state.release?.title)}_vertical.png`));els.licensingBtn.addEventListener('click',()=>downloadBlob(textBlob(commercialLicensingText(state.release)),'commercial_licensing_cue_sheet.txt'));els.growthTextBtn.addEventListener('click',()=>downloadBlob(textBlob(growthPlanText(state.release)),'captions_and_growth_plan.txt'));
els.packageBtn.addEventListener('click',async()=>{if(!state.release)return;els.packageBtn.disabled=true;els.packageBtn.textContent='Building ZIP…';try{downloadBlob(await makeZip(getPackageFiles()),`${safeFilename(state.release.title)}_complete_release.zip`);}finally{els.packageBtn.disabled=false;els.packageBtn.textContent='⬇ Download Full Release + Growth ZIP';}});
els.copyLyricsBtn.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.release?.lyrics||'');els.copyLyricsBtn.textContent='Copied';els.copyLyricsBtn.classList.add('copy-ok');setTimeout(()=>{els.copyLyricsBtn.textContent='Copy lyrics';els.copyLyricsBtn.classList.remove('copy-ok');},1200);}catch(_){}});
els.applyTitleBtn.addEventListener('click',async()=>{if(!state.release)return;const n=normalizeText(els.titleInput.value);if(!n)return;const old=state.release.title;state.release.title=n;state.release.lyrics=replaceTitleInLyrics(state.release.lyrics,old,n);state.coverBlob=await makeCover(n,state.release.artist,state.release.seed);state.coverUrl&&URL.revokeObjectURL(state.coverUrl);state.coverUrl=URL.createObjectURL(state.coverBlob);els.coverPreview.src=state.coverUrl;refreshReleaseUI();});
els.newTitleBtn.addEventListener('click',async()=>{if(!state.release)return;const rng=mulberry32(randomSeed('title')),old=state.release.title,n=makeTitle(state.release.prompt,rng);state.release.title=n;state.release.lyrics=replaceTitleInLyrics(state.release.lyrics,old,n);state.coverBlob=await makeCover(n,state.release.artist,randomSeed('cover'));state.coverUrl&&URL.revokeObjectURL(state.coverUrl);state.coverUrl=URL.createObjectURL(state.coverBlob);els.coverPreview.src=state.coverUrl;refreshReleaseUI();});
els.newLyricsBtn.addEventListener('click',async()=>{if(!state.release)return;const rng=mulberry32(randomSeed('lyrics'));state.release.lyrics=makeLyrics(state.release.prompt,state.release.title,rng);await rerenderVocalsOnly();});
els.newCoverBtn.addEventListener('click',async()=>{if(!state.release)return;state.coverBlob=await makeCover(state.release.title,state.release.artist,randomSeed('cover'));state.coverUrl&&URL.revokeObjectURL(state.coverUrl);state.coverUrl=URL.createObjectURL(state.coverBlob);els.coverPreview.src=state.coverUrl;});els.newAudioBtn.addEventListener('click',createFullRelease);
els.clearHistoryBtn.addEventListener('click',()=>{try{localStorage.removeItem(HISTORY_KEY);}catch(_){}renderHistory();});els.diagnosticsBtn.addEventListener('click',runDiagnostics);

loadProfile();loadEarnings();renderEarnings();renderHistory();renderImportStatus();runDiagnostics();if(els.studioApiUrl.value.trim()){els.studioStatus.textContent='Studio URL saved. Tap Test Studio connection, or Auto mode will try it when you create a song.';}
